import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for matrix multiplication with vectorized access
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 16
#define THREAD_TILE_M 4
#define THREAD_TILE_N 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ float Bs[BLOCK_SIZE][BLOCK_SIZE];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    // Each thread computes THREAD_TILE_M x THREAD_TILE_N elements
    float c[THREAD_TILE_M][THREAD_TILE_N] = {0.0f};

    for (int tile = 0; tile < (N + BLOCK_SIZE - 1) / BLOCK_SIZE; tile++) {
        // Load tiles into shared memory
        int row = by * BLOCK_SIZE + ty;
        int col = tile * BLOCK_SIZE + tx;
        if (row < N && col < N) {
            As[ty][tx] = A[row * N + col];
        } else {
            As[ty][tx] = 0.0f;
        }

        row = tile * BLOCK_SIZE + ty;
        col = bx * BLOCK_SIZE + tx;
        if (row < N && col < N) {
            Bs[ty][tx] = B[row * N + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        // Compute using register tiling
        for (int k = 0; k < BLOCK_SIZE; k++) {
            for (int m = 0; m < THREAD_TILE_M; m++) {
                for (int n = 0; n < THREAD_TILE_N; n++) {
                    int a_row = ty + m * (BLOCK_SIZE / THREAD_TILE_M);
                    int b_col = tx + n * (BLOCK_SIZE / THREAD_TILE_N);
                    if (a_row < BLOCK_SIZE && b_col < BLOCK_SIZE) {
                        c[m][n] += As[a_row][k] * Bs[k][b_col];
                    }
                }
            }
        }

        __syncthreads();
    }

    // Write results back to global memory
    for (int m = 0; m < THREAD_TILE_M; m++) {
        for (int n = 0; n < THREAD_TILE_N; n++) {
            int row = by * BLOCK_SIZE + ty + m * (BLOCK_SIZE / THREAD_TILE_M);
            int col = bx * BLOCK_SIZE + tx + n * (BLOCK_SIZE / THREAD_TILE_N);
            if (row < N && col < N) {
                C[row * N + col] = c[m][n];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block(BLOCK_SIZE / THREAD_TILE_N, BLOCK_SIZE / THREAD_TILE_M);
    dim3 grid((N + BLOCK_SIZE - 1) / BLOCK_SIZE, (N + BLOCK_SIZE - 1) / BLOCK_SIZE);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(), 
        B.data_ptr<float>(), 
        C.data_ptr<float>(), 
        N
    );

    return C;
}
"""

